arguments.new_str:
class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: GetEnvironmentVariable returns null for
        // empty env vars on Unix. Use string.IsNullOrEmpty to preserve the
        // old "not set" vs "explicitly empty" distinction is no longer
        // possible via this API alone; check existence via /proc/self/environ
        // or use a sentinel. Here we read the raw environment block.
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val == null && !EnvironmentVariableExists("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    // .NET 9: empty env vars return null on Unix, same as unset.
    // To distinguish "unset" from "set-but-empty", inspect the process env.
    private static bool EnvironmentVariableExists(string name)
    {
        var envs = Environment.GetEnvironmentVariables();
        return envs.Contains(name);
    }
}

